func:
// ==================================================================
// NORMALIZACIÓN, FILTRADO Y MODELO EDAFOCLIMÁTICO FAO PENMAN-MONTEITH
// ==================================================================
let data = msg.payload;
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch(e) {
        node.error("Payload JSON inválido", msg);
        return null;
    }
}

// 1. Sanear variables numéricas
let vwc = parseFloat(data.humedad_vwc) || 0.0;
let temp = parseFloat(data.temperatura) || 0.0;
let rh = parseFloat(data.humedad_aire) || 0.0;
let trigger = parseFloat(data.umbral_trigger) || 27.0;
let bomba = String(data.bomba_estado || 'OFF').toUpperCase();
let timeout = parseInt(data.alerta_timeout) || 0;

// 2. Cálculo formal del Déficit de Presión de Vapor (VPD en kPa)
// Ecuación Magnus-Tetens: es = 0.6108 * exp((17.27 * T) / (T + 237.3))
let es = 0.6108 * Math.exp((17.27 * temp) / (temp + 237.3));
let ea = es * (rh / 100.0);
let vpd = parseFloat((es - ea).toFixed(2));

// 3. Estructura normalizada estandarizada
msg.payload = {
    dispositivo_id: data.dispositivo || "ESP32_Planta01",
    timestamp: new Date().toISOString(),
    metricas: {
        humedad_vwc: parseFloat(vwc.toFixed(1)),
        temperatura_c: parseFloat(temp.toFixed(1)),
        humedad_relativa: parseFloat(rh.toFixed(1)),
        vpd_kpa: vpd,
        umbral_mad: trigger
    },
    actuador: {
        bomba_estado: bomba,
        alerta_timeout: timeout
    },
    evaluacion: {
        estres_hidrico: vwc <= trigger,
        marchitez_critica: vwc <= 15.0,
        estres_termico: temp > 35.0 || temp < 8.0,
        estres_transpiratorio: vpd > 1.8
    }
};

return msg;

msg.payload = {
    tipo: "ALERTA_FAIL_SAFE",
    severidad: "CRITICA",
    mensaje: "⚠️ [EMERGENCIA FAIL-SAFE] La bomba superó los 10 segundos máximos de operación. Apagado de protección activado para evitar inundación.",
    timestamp: new Date().toISOString()
};
return msg;

let vwc = msg.payload.metricas.humedad_vwc;
msg.payload = {
    tipo: "ESTRES_HIDRICO_SEVERO",
    severidad: "ALTA",
    mensaje: `🚨 [PUNTO DE MARCHITEZ] Humedad crítica en ${vwc}% VWC (límite 15%). Iniciando protocolo de recuperación hídrica.`,
    timestamp: new Date().toISOString()
};
return msg;

let vwc = msg.payload.metricas.humedad_vwc;
let vpd = msg.payload.metricas.vpd_kpa;
msg.payload = {
    tipo: "RIEGO_NECESARIO",
    severidad: "MEDIA",
    mensaje: `💧 [ACTIVACIÓN MAD] Humedad en ${vwc}% VWC (<= 27%). Déficit de Presión de Vapor: ${vpd} kPa. Riego automatizado en curso.`,
    timestamp: new Date().toISOString()
};
return msg;

// Solo enviar ON si la bomba está actualmente OFF para evitar flooding
if (msg.payload.actuador && msg.payload.actuador.bomba_estado === 'ON') {
    return null;
}
msg.topic = "hogar/planta01/control";
msg.payload = "ON";
return msg;

if (msg.payload.actuador && msg.payload.actuador.bomba_estado === 'OFF') {
    return null;
}
msg.topic = "hogar/planta01/control";
msg.payload = "OFF";
return msg;
